  const src = Array.isArray(inv) ? inv : [];
  return src.filter((it) => it && it.name).map((it) => {
    let n = parseInt(it.count, 10);
    if (!Number.isFinite(n) || n < 1) n = 1;
    return { ...it, id: it.id || itemIdOf(it.name), name: String(it.name), count: n };
