function warnIdentityMismatch(p, messageId) { return XSD_STATUS_APPLICATION.warnIdentityMismatch(p, messageId); }
function findDeclaredFaction(raw) { return XSD_STATUS_APPLICATION.findDeclaredFaction(raw); }
