  }
  function datePatch(sd,date,token,tx) {
    const m=/^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(date||'');
    if(!m)throw Error('日期用年-月-日填写');
    const y=+m[1],mo=+m[2],d=+m[3]; if(y<1000||mo<1||mo>12||d<1||d>30)throw Error('日期范围错误（每月30日）');
