    let hi = 0;
    for (let n = 1; n <= rel.a; n++) { if (K[rel.s + XSD_RELIC_CN[n] + '阶段'] === true) hi = n; }
    const arcs = Math.max(1, hi);

    const idText = s0(identity);
    const isLord = (lord, hall) => {
